// Lightweight, original vector illustrations. Meaningful movement is added by CSS.
export function art(kind='island',cls=''){
const fox=`<g class="fox-character"><path d="M-35 5Q-68-2-63 30Q-46 48-30 27" fill="#ce794d"/><path d="M-60 11Q-70 28-54 34L-48 20Z" fill="#fff0d5"/><ellipse cx="0" cy="29" rx="30" ry="29" fill="#e49a60"/><path d="M-30 0-29-36-8-22 13-24 32-37 33 0Q28 28 0 28T-30 0Z" fill="#eea369"/><path d="m-25-26 1 18 13-11M25-27 1 17-13-10" fill="#ad664c"/><path d="M-29 4Q-18 0 0 14Q18 0 31 4Q24 32 0 29T-29 4" fill="#fff0d5"/><ellipse cx="-11" cy="1" rx="2.6" ry="3.6" fill="#41483e"/><ellipse cx="12" cy="1" rx="2.6" ry="3.6" fill="#41483e"/><path d="m-5 14 5 5 5-5" fill="#41483e"/><path d="M-15 50v9M15 50v9" stroke="#9c654c" stroke-width="10" stroke-linecap="round"/><path d="M-28 22Q0 32 29 22L25 35Q0 42-25 35" fill="#4b7c6c"/><path d="m18 30 3 22 10-7-5-17" fill="#4b7c6c"/></g>`;
const tree=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 0v67" stroke="#90775a" stroke-width="9"/><path d="M-33 22Q-53-5-25-22Q-32-58 0-59Q31-59 32-28Q62-7 31 24Z" fill="#84a986"/><path d="M0-35v63m0-25-18-16m18 0L18-7" fill="none" stroke="#6d9475" stroke-width="3"/></g>`;
const cloud=(x,y)=>`<path class="cloud" d="M${x} ${y}q-15-20 7-24q8-29 31-9q23-13 26 11q26 11 0 24Z" fill="#fffdf4"/>`;
const sparkle=`<g fill="#c5a257"><path d="m50 80 4 11 11 4-11 4-4 11-4-11-11-4 11-4Z"/><path d="m450 60 3 8 8 3-8 3-3 8-3-8-8-3 8-3Z"/></g>`;
let inside='';
if(kind==='island') inside=`<rect width="560" height="390" rx="40" fill="#e9eee3"/>${cloud(62,79)}${cloud(410,112)}<circle cx="397" cy="63" r="28" fill="#efd99f"/><ellipse cx="281" cy="327" rx="221" ry="34" fill="#b5cfbe"/><path d="M60 265Q97 180 207 189Q247 125 335 162Q429 137 502 258L454 314Q260 374 96 310Z" fill="#c7d9af"/><path d="M93 285Q206 325 453 281" fill="none" stroke="#f4e6bd" stroke-width="23"/><path d="M130 265Q230 273 278 218T433 239" fill="none" stroke="#f7edcf" stroke-width="16"/>${tree(112,197,.8)}${tree(460,196,.78)}${tree(383,164,.55)}<g transform="translate(218 172)"><rect width="91" height="74" rx="6" fill="#f1dfb4"/><path d="M-13 6 46-45 104 6Z" fill="#d9855f"/><rect x="33" y="32" width="26" height="42" rx="13" fill="#698c72"/><rect x="11" y="20" width="16" height="19" rx="5" fill="#fff9dd"/><path d="M75-18v-22h11v32" fill="#ac6b51"/></g><g transform="translate(170 264) scale(.78)">${fox}</g><g transform="translate(366 268)"><rect x="-25" y="-32" width="61" height="40" rx="8" fill="#749f98"/><path d="M-30-26 6-2 40-26" stroke="#e9f0d9" fill="none" stroke-width="3"/><path d="M4 8v30" stroke="#96775a" stroke-width="7"/></g><g transform="translate(338 126) rotate(9)"><rect width="57" height="40" rx="7" fill="#fff9e8"/><text x="28" y="28" font-size="24" text-anchor="middle" fill="#628b74">Aa</text></g>${sparkle}`;
else if(kind==='fox'||kind==='post') inside=`<ellipse cx="280" cy="287" rx="160" ry="23" fill="#d9e4ca"/>${tree(405,203,.7)}<g transform="translate(243 206) scale(1.55)">${fox}</g><g transform="translate(330 179)"><rect width="70" height="50" rx="8" fill="#759e8c"/><path d="m2 5 34 25L68 5" stroke="#edf0d7" fill="none" stroke-width="3"/><path d="M35 50v66" stroke="#96775a" stroke-width="9"/></g>${cloud(110,96)}${sparkle}`;
else if(kind==='train') inside=`<path d="M35 288h490M40 301h480" stroke="#a59677" stroke-width="5"/><g class="train-art"><rect x="69" y="180" width="98" height="80" rx="16" fill="#d48d67"/><rect x="90" y="147" width="57" height="49" rx="8" fill="#efd7a3"/><rect x="102" y="158" width="32" height="25" rx="5" fill="#a8c9bd"/><path d="M59 236h111v24H59Z" fill="#b97454"/>${[190,310,430].map((x,i)=>`<rect x="${x}" y="195" width="99" height="65" rx="12" fill="${['#8cad91','#9fbac8','#c2b0cc'][i]}"/><text x="${x+50}" y="235" text-anchor="middle" font-size="28" fill="#fffdf3">${['S','V','O'][i]}</text><circle cx="${x+22}" cy="274" r="13" fill="#665e4d"/><circle cx="${x+77}" cy="274" r="13" fill="#665e4d"/>`).join('')}<circle cx="94" cy="274" r="14" fill="#665e4d"/><circle cx="148" cy="274" r="14" fill="#665e4d"/></g><g class="smoke" fill="#e3dcca"><circle cx="94" cy="115" r="10"/><circle cx="76" cy="82" r="16"/><circle cx="99" cy="45" r="22"/></g>${cloud(368,107)}`;
else if(kind==='house') inside=`<ellipse cx="284" cy="297" rx="224" ry="24" fill="#dfdfd4"/>${[90,237,384].map((x,i)=>`<g class="house-art" style="--delay:${i*.2}s" transform="translate(${x} ${145-i*12})"><rect x="0" y="35" width="99" height="110" rx="7" fill="${['#edd7b0','#c4d6c1','#d6cee2'][i]}"/><path d="M-13 37 50-15 111 37Z" fill="${['#c98a68','#739786','#aa95b4'][i]}"/><rect x="36" y="96" width="27" height="49" rx="13" fill="#fff8e5"/><rect x="15" y="55" width="23" height="23" rx="5" fill="#fffbec"/><rect x="63" y="55" width="23" height="23" rx="5" fill="#fffbec"/><text x="50" y="-30" text-anchor="middle" font-size="19" fill="#657263">${['S + V','S + V + O','S + V + P'][i]}</text></g>`).join('')}${cloud(168,70)}`;
else if(kind==='clock') inside=`<circle cx="285" cy="173" r="105" fill="#e5eaf0"/><circle cx="285" cy="173" r="82" fill="#fff9e7" stroke="#b7c9c8" stroke-width="5"/>${Array.from({length:12},(_,i)=>`<path d="M285 102v9" stroke="#aab6a5" stroke-width="3" transform="rotate(${i*30} 285 173)"/>`).join('')}<g class="clock-hand"><path d="M285 173v-49m0 49 36 22" stroke="#628576" stroke-width="7" stroke-linecap="round"/></g><circle cx="285" cy="173" r="7" fill="#d69e67"/><path d="M70 306h420" stroke="#b0bcb3" stroke-width="4"/>${[135,285,435].map((x,i)=>`<circle cx="${x}" cy="306" r="8" fill="${['#c5abc5','#d39e68','#8eb5ae'][i]}"/><text x="${x}" y="344" font-size="19" text-anchor="middle" fill="#6d7d73">${['昨天','此刻','每天'][i]}</text>`).join('')}${sparkle}`;
else if(kind==='mirror') inside=`<rect x="296" y="77" width="134" height="208" rx="67" fill="#d4bd8c"/><rect x="307" y="89" width="112" height="182" rx="55" fill="#d7e7df"/><g transform="translate(365 189) scale(.75)">${fox}</g><g transform="translate(185 206) scale(1.35)">${fox}</g><path d="m321 121 63-13m-67 30 79-16" stroke="#edf5e9" stroke-width="5" stroke-linecap="round"/>${sparkle}`;
else if(kind==='bag') inside=`<ellipse cx="280" cy="322" rx="155" ry="22" fill="#d6dfc8"/><path d="M224 108v-29q55-57 110 0v29" fill="none" stroke="#9a8e67" stroke-width="17"/><rect x="170" y="99" width="217" height="208" rx="49" fill="#91ae83"/><rect x="199" y="180" width="160" height="99" rx="22" fill="#b5c49a"/><path d="M195 143h165" stroke="#f1e4b9" stroke-width="7" stroke-linecap="round"/><circle cx="276" cy="217" r="24" fill="#edbf83"/><path d="m259 218 12 12 21-26" stroke="#8b8d61" fill="none" stroke-width="6" stroke-linecap="round"/><g class="cargo-float"><rect x="100" y="145" width="66" height="63" rx="14" fill="#f4e3b4"/><text x="133" y="185" font-size="30" text-anchor="middle">Aa</text></g><g class="cargo-float" style="animation-delay:1s"><path d="M398 160h52l-8 59h-35Z" fill="#c4dae0" stroke="#8eb5b8" stroke-width="4"/><path d="M450 171q30 0 7 28" fill="none" stroke="#8eb5b8" stroke-width="5"/></g>${sparkle}`;
else if(kind==='capsule') inside=`<ellipse cx="280" cy="306" rx="180" ry="22" fill="#dfe5cf"/>${[100,230,360].map((x,i)=>`<g class="cargo-float" style="animation-delay:${i*.6}s"><rect x="${x}" y="145" width="110" height="100" rx="24" fill="${['#b4caab','#d7c6b1','#c5b9d2'][i]}"/><path d="M${x+10} 179h90" stroke="#fff9e6" stroke-width="3"/><text x="${x+55}" y="208" font-size="17" text-anchor="middle" fill="#4a6453">${['reading','to read','what I like'][i]}</text></g>`).join('')}<path d="M100 268h370" stroke="#9cae8b" stroke-width="5"/>${sparkle}`;
else if(kind==='portrait'||kind==='paint') inside=`<path d="M167 113 135 320m174-207 35 207m-122-60v60" stroke="#a68b65" stroke-width="10" stroke-linecap="round"/><rect x="127" y="76" width="226" height="205" rx="12" fill="#cfb185"/><rect x="140" y="89" width="200" height="179" rx="6" fill="#fcf3dc"/><g transform="translate(240 176) scale(1.2)">${fox}</g><circle cx="420" cy="229" r="49" fill="#f3e2b8"/><circle cx="399" cy="218" r="10" fill="#c8846a"/><circle cx="429" cy="207" r="10" fill="#8ba982"/><circle cx="440" cy="237" r="10" fill="#91b1be"/><path d="m366 164 70-58 11 14-69 58" fill="#9c8b61"/><path d="m435 107 17-24 7 19-13 18" fill="#c78766"/>${sparkle}`;
else if(kind==='director') inside=`<ellipse cx="280" cy="320" rx="188" ry="21" fill="#d8e2d1"/><rect x="95" y="140" width="197" height="146" rx="14" fill="#7e9c90"/><path d="m95 139 185-52 12 45-195 53Z" fill="#536c61"/>${[0,1,2,3].map(i=>`<path d="m${110+i*45} ${134-i*12} 23 36 24-7-23-36Z" fill="#e9e7cf"/>`).join('')}<text x="195" y="220" text-anchor="middle" font-size="26" fill="#fff2d2">ACTION!</text><path d="M129 247h129" stroke="#b6cfbb" stroke-width="3"/><g transform="translate(392 224) scale(1.05)">${fox}</g><path d="M340 300h121" stroke="#a6b794" stroke-width="4" stroke-dasharray="4 11"/>${sparkle}`;
else if(kind==='bird') inside=`${tree(405,198,1.2)}<path d="M110 233h260" stroke="#967e61" stroke-width="11" stroke-linecap="round"/><g class="bird-art"><ellipse cx="244" cy="176" rx="65" ry="52" fill="#8daea1"/><circle cx="286" cy="140" r="35" fill="#8daea1"/><path d="m317 137 28 10-29 9" fill="#d6a064"/><path d="M220 168q-25-49-52-37q5 63 69 76" fill="#6f9587"/><circle cx="295" cy="131" r="4" fill="#394c40"/><path d="M237 216v16m24-16v16" stroke="#9c7955" stroke-width="5"/></g><text x="140" y="106" font-size="36" fill="#8eaa82" class="note">♪</text><text x="353" y="104" font-size="29" fill="#b6a5c3" class="note">♫</text>`;
else if(kind==='flower') inside=`<ellipse cx="279" cy="297" rx="150" ry="18" fill="#e0e6d2"/>${[185,280,375].map((x,i)=>`<g transform="translate(${x} ${175-i%2*26})"><path d="M0 0v115" stroke="#81a57b" stroke-width="7"/><path d="M0 58q-56-41-40 0q17 25 40 2m0 22q55-44 40-5q-16 27-40 6" fill="#a5bf8d"/><g class="petals">${[0,60,120,180,240,300].map(d=>`<ellipse cx="0" cy="-22" rx="15" ry="24" fill="${['#ddb295','#d5b7c8','#e6cb85'][i]}" transform="rotate(${d})"/>`).join('')}<circle r="13" fill="#f8e5af"/></g></g>`).join('')}`;
else if(kind==='cloud') inside=`<ellipse cx="280" cy="318" rx="155" ry="18" fill="#dce5d5"/><path d="M160 205q-43-8-31-46q6-34 46-31q7-64 69-61q53-2 67 45q50-21 73 15q49 2 48 43q0 38-47 39Z" fill="#b9d2d2" stroke="#91b3b4" stroke-width="3"/><g class="renewal-rain" stroke="#91b5c3" stroke-width="7" stroke-linecap="round"><path d="m190 238-9 24m71-24-9 24m71-24-9 24m71-24-9 24"/></g>`;
else if(kind==='snow') inside=`<ellipse cx="280" cy="316" rx="155" ry="18" fill="#e0e6dc"/><path d="M263 103a24 24 0 0 1 48 0v133a45 45 0 1 1-48 0Z" fill="#f4f4e7" stroke="#9ebcbd" stroke-width="7"/><path d="M287 166v99" stroke="#a9c9d2" stroke-width="16" stroke-linecap="round"/><circle cx="287" cy="270" r="22" fill="#a9c9d2"/><g stroke="#a6bfc9" stroke-width="4">${[150,415].map((x,i)=>`<path d="M${x} ${150+i*50}v50m-22-38 44 25m-44 0 44-25"/>`).join('')}</g>`;
else if(kind==='sign') inside=`<path d="M280 160v155" stroke="#a58d64" stroke-width="14"/><path d="M140 95h250l45 52-45 52H140Z" fill="#b7cddd" stroke="#91adbb" stroke-width="4"/><path d="M180 134h170m-170 24h120" stroke="#f5f2df" stroke-width="7" stroke-linecap="round"/><ellipse cx="280" cy="320" rx="90" ry="10" fill="#dce3cd"/>`;
else if(kind==='tree') inside=`<ellipse cx="280" cy="300" rx="170" ry="23" fill="#dce5d3"/>${tree(280,180,1.7)}${cloud(75,107)}${sparkle}`;
else {const symbols={apple:'🍎',rabbit:'🐇',turtle:'🐢',moon:'🌙',star:'⭐',bowl:'🥣',book:'📖',ball:'⚽',box:'📦',water:'💧',cat:'🐈',dog:'🐕',door:'🚪',cake:'🍰',sky:'☁️',gift:'🎁',bag:'🎒',paint:'🎨',music:'🎵',camera:'📷',map:'🗺️',search:'🔎',link:'🔗',bridge:'🌉',rocket:'🚀',film:'🎞️',leaf:'🌱'};inside=`<ellipse cx="280" cy="299" rx="130" ry="19" fill="#dce5d3"/><circle cx="280" cy="173" r="106" fill="#e8eddf"/><text class="symbol-art" x="280" y="221" font-size="124" text-anchor="middle">${symbols[kind]||'🌱'}</text>${sparkle}`;}
return `<svg class="art ${cls}" viewBox="0 0 560 390" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${inside}</svg>`;
}
